# conteúdo que será assinado nas avaliações do avaliador
def conteudo_a_ser_assinado(apps, avaliacao, tipo_assinatura):
    Vinculo = apps.get_model('comum', 'Vinculo')
    Servidor = apps.get_model('rh', 'Servidor')
    qs = None
    lista_string_conteudo = []
    if tipo_assinatura == CIENCIA:
        lista_string_conteudo = [f"pontuacao_final:{avaliacao.pontuacao_final}"]
    #
    if 'edu' in installed_apps:
        tipo_objeto = ContentType.objects.get_for_model(apps.get_model('edu.aluno'))
        qs = avaliacao.avaliacaoitem_set.exclude(responsavel__tipo_relacionamento_id=tipo_objeto.id)
    else:
        qs = avaliacao.avaliacaoitem_set.all()
    for i in qs:
        pontuacao = i.pontuacao_form
        if not pontuacao and pontuacao != 0:
            pontuacao = i.pontuacao.pontos
        item_pk = i.item.pk
        #
        responsavel = 'None'
        if i.responsavel:
            try:
                servidor = Servidor.objects.get(pessoa_fisica__user=i.responsavel.user)
                responsavel = f"{servidor.pessoa_fisica.nome} ({servidor.matricula})"
            except Exception:
                pass
        #
        responsavel_avaliacao = 'None'
        if i.responsavel_avaliacao:
            try:
                servidor = Servidor.objects.get(pessoa_fisica__user=i.responsavel_avaliacao.user)
                responsavel_avaliacao = f"{servidor.pessoa_fisica.nome} ({servidor.matricula})"
            except Exception:
                pass
        lista_string_conteudo.append(slugify(f"{item_pk} {pontuacao} {responsavel} {responsavel_avaliacao}"))
    conteudo_completo = "|".join(lista_string_conteudo)
    return conteudo_completo

# chave
def chave_a_ser_utilizada_na_assinatura(avaliacao, tipo_assinatura):
    chave = slugify(f"{avaliacao.pk} {avaliacao.progressao.pk} {avaliacao.progressao.avaliado}")
    if tipo_assinatura == CIENCIA:
        chave = slugify(f"{avaliacao.pk} {avaliacao.progressao.pk} {avaliacao.progressao.avaliado} {avaliacao.pontuacao_final}")
    return chave

# gera a assinatura
def gera_assinatura(conteudo, chave):
    autenticador = hashlib.sha1(f'{conteudo}{chave}'.encode()).hexdigest()
    chave_codificada_num_rodadas = random.randrange(2, 5)
    chave_codificada = f'{chave}'
    for _rodada in range(1, chave_codificada_num_rodadas + 1):
        chave_codificada = b64encode(f'{chave_codificada}')
    assinatura = b64encode(f'{autenticador},{chave_codificada_num_rodadas},{chave_codificada}')
    return assinatura

# corrigindo as assinaturas
def correcao_assinaturas(apps, schema):
    Avaliacao = apps.get_model('progressao_docente', 'Avaliacao')
    for avaliacao in tqdm.tqdm(Avaliacao.objects.all()):
        if avaliacao.assinatura_avaliador:
            conteudo = conteudo_a_ser_assinado(apps, avaliacao, AVALIACAO)
            chave = chave_a_ser_utilizada_na_assinatura(avaliacao, AVALIACAO)
            nova_assinatura = gera_assinatura(conteudo=conteudo, chave=chave)
            avaliacao.string_assinatura_avaliador = conteudo
            avaliacao.assinatura_avaliador = nova_assinatura
            avaliacao.save()
        if avaliacao.assinatura_avaliado_processo:
            conteudo = conteudo_a_ser_assinado(apps, avaliacao, CIENCIA)
            chave = chave_a_ser_utilizada_na_assinatura(avaliacao, CIENCIA)
            nova_assinatura = gera_assinatura(conteudo=conteudo, chave=chave)
            avaliacao.string_assinatura_avaliado_processo = conteudo
            avaliacao.assinatura_avaliado_processo = nova_assinatura
            avaliacao.save()

